#include <bits/stdc++.h>using namespace std; using ll = long long; void solve() {    ll n;    cin >> n;     vector<pair<ll,ll>> a(n);     //  Input + store original index    for (int i = 0; i < n; i++) {        cin >> a[i].first;        a[i].second = i;    }     //  Sort by value    sort(a.begin(), a.end());     //  Prefix sum    vector<ll> pref(n);    pref[0] = a[0].first;    for (int i = 1; i < n; i++) {        pref[i] = pref[i - 1] + a[i].first;    }     vector<ll> ans(n);     //  t = start of current segment    ll t = n;     //  Traverse from right → left    for (int i = n - 1; i > 0; i--) {         // assign answer        ans[a[i].second] = t - 1;         // if cannot merge with previous → new segment        if (a[i].first > pref[i - 1]) {            t = i;        }    }     //  handle first element    ans[a[0].second] = t - 1;     //  Output    for (int i = 0; i < n; i++) {        cout << ans[i] << " ";    }    cout << "\n";} int main() {    ios::sync_with_stdio(false);    cin.tie(NULL);     int t;    cin >> t;     while (t--) {        solve();    }     return 0;}